python3 <<'EOF'
import json, collections

base = "bench/results/2026-10-12/m1-ngram/replay"
phases = ["single-agent", "single-mem", "dual-agent", "dual-mem"]

def load(cfg):
    rows = {}
    for r in json.lines(open(f"{base}/{cfg}-greedy/requests.jsonl")):
        row = json.loads(r)
        rows.setdefault((row["phase"], row["id"]), row)
    return rows

sets = {}
for cfg in ["off", "A", "B"]:
    sets[cfg] = []
    for r in json.lines(open(f"{base}/{cfg}-greedy/requests.jsonl")):
        sets[cfg].append(json.loads(r))

print("=== per-phase, per-config fg stats ===")
for cfg in ["off","A","B"]:
    print(f"\n{cfg}:")
    for ph in phases:
        fg = [r for r in sets[cfg] if r["phase"]==ph and r["fg_bg"]=="fg"]
        bg = [r for r in sets[cfg] if r["phase"]==ph and r["fg_bg"]=="bg"]
        def stats(rs):
            n = sum(r["predicted_n"] for r in rs); ms = sum(r["predicted_ms"] for r in rs)
            return n, ms, n/ms/1000 if ms else None, len(rs)
        n,ms,ps,c = stats(fg)
        nlen = [r for r in fg if r["finish_reason"]=="length"]
        n_nolen, ms_nolen, ps_nolen,_ = stats([r for r in fg if r["finish_reason"]!="length"])
        print(f"  {ph:15s} fg: n={n:>5d} ms={ms/1000:8.1f}s ps={ps:5.1f} rows={c} | w/o length: n={n_nolen:>5d} ps={ps_nolen:5.1f} | length rows: {len(nlen)}")
        for r in nlen:
            print(f"     length row {r['id']}: pred_n={r['predicted_n']} ms={r['predicted_ms']:.0f}")
        if bg:
            n,ms,ps,c = stats(bg)
            print(f"  {ph:15s} bg: n={n:>5d} ms={ms/1000:8.1f}s ps={ps:5.1f} rows={c} | combined (fg+bg)/fg_ms = {(n+sum(rr['predicted_n'] for rr in bg))/sum(rr['predicted_ms'] for rr in fg)/1000:.1f} ps")
        else:
            n,ms,ps,c = stats(fg)
        dn = sum(r.get("draft_n") or 0 for r in fg)
        dna = sum(r.get("draft_n_accepted") or 0 for r in fg)
        print(f"  {ph:15s} draft fg: {dn} / {dna} ({dna/dn*100 if dn else 0:.0f}%)")
EOF

